-- =====================================================================================
-- Hand-port: force utf8mb4_unicode_ci on view columns that MariaDB otherwise gives the CHARSET
-- DEFAULT collation (utf8mb4_general_ci).
--
-- CAST(x AS CHAR) is stored by MariaDB as `cast(x as char charset utf8mb4)`, and FORMAT(x,n)
-- behaves the same: the result takes the charset's DEFAULT collation (general_ci) and IGNORES
-- collation_connection - even though every view here was created with collation_connection =
-- utf8mb4_unicode_ci (verified via information_schema.VIEWS: 31 of 31 correct).
--
-- Consequence: those columns came out general_ci, and any view UNIONing them against a normal
-- unicode_ci column failed hard with 'ERROR 1271 Illegal mix of collations for operation UNION'.
-- exchangeaccdata_notaccid and exchangeaccdata_notaccid_cosumer were completely unusable - they
-- could not even be SHOW CREATEd, which ALSO made mysqldump abort on the entire schema and so
-- blocked the production deployment.
--
-- Fix: append COLLATE utf8mb4_unicode_ci to every CAST(..AS CHAR)/FORMAT() expression in these
-- views. Values are untouched - only the collation label changes - so comparisons and sorting
-- now agree with every other column. Views are recreated in dependency order (sources first).
-- =====================================================================================
USE EXCHANGESYS2026;
SET NAMES utf8mb4;
SET collation_connection='utf8mb4_unicode_ci';

-- exchangeaccdata : 4 CAST + 0 FORMAT expression(s) pinned to unicode_ci
CREATE OR REPLACE VIEW `exchangeaccdata` AS
select `x`.`AccCode` AS `AccCode`,`x`.`AccID` AS `AccID`,`x`.`AccName` AS `AccName`,`x`.`TransDate` AS `TransDate`,`x`.`TransValue` AS `TransValue`,`x`.`Type_trns` AS `Type_trns`,`x`.`commint` AS `commint`,`x`.`Code` AS `Code`,`x`.`STates_spinng` AS `STates_spinng`,`x`.`Type_from` AS `Type_from`,`x`.`IsActive` AS `IsActive`,case when `x`.`STates_spinng` = 'غير معتمده' then 1 when `x`.`STates_spinng` = 'غير مسلمه' then 2 when `x`.`STates_spinng` = 'مسلمه' then 3 when `x`.`STates_spinng` = 'تحويل لحساب' then 3 else 3 end AS `STates_Ineger`,`x`.`ServiceName` AS `ServiceName`,`x`.`CName` AS `CName`,`x`.`TransPrice` AS `TransPrice`,`x`.`NetTotal` AS `NetTotal`,`x`.`ServiceExVal` AS `ServiceExVal`,`x`.`Notes` AS `Notes`,`x`.`Driver_ID` AS `Driver_ID`,`x`.`uesrID_forminsertmobile` AS `uesrID_forminsertmobile` from (select `a`.`TransDate` AS `TransDate`,`a`.`TransValue` AS `TransValue`,`c`.`AccName` AS `AccName`,cast(`c`.`AccPhone` as char charset utf8mb4) collate utf8mb4_unicode_ci AS `AccCode`,`b`.`AccID` AS `AccID`,`a`.`IsActive` AS `IsActive`,`a`.`Code` AS `Code`,'تحويل بين الحسبات' AS `Type_trns`,0 AS `commint`,'تحويل لحساب' AS `STates_spinng`,1 AS `Type_from`,'' AS `ServiceName`,'' AS `CName`,0.00 AS `TransPrice`,0.00 AS `NetTotal`,0.00 AS `ServiceExVal`,`a`.`Notes` AS `Notes`,`a`.`Driver_ID` AS `Driver_ID`,`a`.`uesrID_forminsertmobile` AS `uesrID_forminsertmobile` from ((`exchangesys2026`.`transbetweenaccountstb` `a` join `exchangesys2026`.`accountstb` `b` on(`a`.`TransFrom` = `b`.`AccID`)) join `exchangesys2026`.`accountstb` `c` on(`a`.`TransTo` = `c`.`AccID`)) union all select `a`.`InsertDate` AS `InsertDate`,`a`.`OverallVal` AS `OverallVal`,`c`.`AccName` AS `AccName`,cast(`c`.`AccCode` as char charset utf8mb4) collate utf8mb4_unicode_ci AS `CAST(c.AccCode AS CHAR)`,`b`.`AccID` AS `AccID`,`a`.`IsActive` AS `IsActive`,`a`.`Code` AS `Code`,'حوالة داخلية' AS `Type_trns`,`a`.`ExVal` AS `ExVal`,`d`.`SName` AS `STates_spinng`,2 AS `Type_from`,'' AS `ServiceName`,'' AS `C