,`c`.`ServiceName` AS `ServiceName`,`d`.`CName` AS `CName`,`a`.`TransPrice` AS `TransPrice`,`a`.`NetTotal` AS `NetTotal`,`a`.`ServiceExVal` AS `ServiceExVal`,`a`.`Notes` AS `Notes`,`a`.`Driver_ID` AS `Driver_ID`,`a`.`uesrID_forminsertmobile` AS `uesrID_forminsertmobile` from (((`exchangesys2026`.`externalex` `a` join `exchangesys2026`.`accountstb` `b` on(`a`.`AccFrom` = `b`.`AccID`)) join `exchangesys2026`.`exttraservicetypetb` `c` on(`a`.`ServiceType` = `c`.`ID`)) join `exchangesys2026`.`countirestb` `d` on(`a`.`CountryIDTo` = `d`.`ID`))) `x`;

